export type Project = {
  slug: string;
  title: string;
  kicker: Copy;
  summary: Copy;
  problem: Copy;
  constraint: Copy;
  approach: Copy;
  outcome: Copy;
  caseStudyPending?: Copy;
  stack: string[];
  category: 'AI systems' | 'Privacy / local-first' | 'Developer tools' | 'Data / analytics' | 'Creative engineering' | 'Web apps' | 'Mobile apps' | 'Promotional';
  status: Copy;
  source?: string;
  live?: string;
  /** Página do app na App Store por idioma (loja dos EUA em en, do Brasil em pt). Só para app publicado. */
  appStore?: Copy;
  /** Omitted when no verified capture exists; the UI renders a terminal plate instead of inventing one. */
  image?: string;
  alt: Copy;
  featured: boolean;
  openSource: boolean;
  diagram: string[];
  /** Release stage; omitted means live. Anything not live is shown as "in motion" and never counted as public. */
  stage?: Stage;
  /** Older or promotional work: kept routable, listed after current work in the index. */
  archived?: boolean;
};

export type Stage = 'live' | 'appReview' | 'beta' | 'building';

export const stageLabels: Record<Stage, Copy> = {
  live: { en: 'Live', pt: 'No ar' },
  appReview: { en: 'In App Store review', pt: 'Em revisão na App Store' },
  beta: { en: 'Beta', pt: 'Beta' },
  building: { en: 'In construction', pt: 'Em construção' },
};

export const stageOf = (project: Project): Stage => project.stage ?? 'live';
export const isInMotion = (project: Project) => stageOf(project) !== 'live';

/** Public means live with a destination a visitor can open; the stat rail and terminal count only these. */
export const isPublic = (project: Project) => stageOf(project) === 'live' && Boolean(project.live || project.source || project.appStore);

