type PortfolioProjectInput = Pick<Project, 'slug' | 'title' | 'kicker' | 'summary' | 'stack' | 'category' | 'status' | 'openSource' | 'appStore' | 'stage' | 'archived'> & {
  featured?: boolean;
  image?: string;
  source?: string;
  live?: string;
  // Supply all four to publish a case study; omit them to keep the visible "pending" block.
  problem?: Copy;
  constraint?: Copy;
  approach?: Copy;
  outcome?: Copy;
  diagram?: string[];
};

const portfolioDetailPending: Copy = {
  en: 'The public portfolio listing is the verified source for this project. A longer case study is still a content TODO.',
  pt: 'A listagem pública do portfólio é a fonte verificada deste projeto. Um case study mais longo ainda é um TODO de conteúdo.',
};

function portfolioProject(input: PortfolioProjectInput): Project {
  const written = Boolean(input.problem && input.constraint && input.approach && input.outcome);
  return {
    ...input,
    problem: input.problem ?? portfolioDetailPending,
    constraint: input.constraint ?? portfolioDetailPending,
    approach: input.approach ?? portfolioDetailPending,
    outcome: input.outcome ?? portfolioDetailPending,
    ...(written ? {} : { caseStudyPending: portfolioDetailPending }),
    alt: {
      en: `${input.title}: product screen.`,
      pt: `${input.title}: tela do produto.`,
    },
    featured: input.featured ?? false,
    diagram: input.diagram ?? ['public portfolio listing', 'verified source link', 'case study pending'],
  };
}

